static DWORD analysis_test_scan(const wchar_t *root,int wsl,int as_root,HANDLE cancel,space_emit emit,void *user,int mode){
 if(mode!=3||!inject_partial_analysis)return space_scan_mode(root,wsl,as_root,cancel,emit,user,mode);
 InterlockedIncrement(&analysis_scans);query_job *job=user;
 const sp_record records[]={
 {.magic=SP_MAGIC,.type=SP_RESET,.identity=SP_BACKEND_ANALYSIS},
 {.magic=SP_MAGIC,.type=SP_ENTRY,.parent=SP_NONE,.flags=SP_DIR,.device=job->device,.identity=job->identity},
 {.magic=SP_MAGIC,.type=SP_ENTRY,.id=1,.parent=0,.logical=17,.allocated=4096},
 {.magic=SP_MAGIC,.type=SP_ENTRY,.id=2,.parent=0,.flags=SP_FAILED|SP_SKIP,.error=ERROR_ACCESS_DENIED},
 {.magic=SP_MAGIC,.type=SP_LEAVE,.id=0},
 {.magic=SP_MAGIC,.type=SP_END,.flags=SP_PARTIAL,.error=0}};
 const wchar_t *names[]={NULL,L"",L"visible.txt",L"denied",NULL,NULL};
 for(unsigned i=0;i<sizeof records/sizeof *records;i++)if(WaitForSingleObject(cancel,0)==WAIT_OBJECT_0||!emit(user,&records[i],names[i]))return ERROR_CANCELLED;return 0;
}
static volatile LONG query_calls;static HANDLE query_gate,query_entered;
