static sp_row *counted_query_finish(sp_query *q,HANDLE cancel,uint32_t *count,DWORD *error){InterlockedIncrement(&query_calls);if(query_gate){SetEvent(query_entered);HANDLE events[]={cancel,query_gate};DWORD status=WaitForMultipleObjects(2,events,FALSE,10000);if(status!=WAIT_OBJECT_0+1){*count=0;*error=status==WAIT_OBJECT_0?ERROR_CANCELLED:ERROR_TIMEOUT;return NULL;}}return space_query_finish(q,cancel,count,error);}
