 uint64_t logical[80]={0},allocated[80]={0},files[80]={0};int built=1;for(unsigned i=0;i<1200;i++){wchar_t name[80];swprintf(name,80,i&1?L"item%04u.T%02u":L"item%04u.t%02u",i,i%80);r=(sp_record){.magic=SP_MAGIC,.type=SP_ENTRY,.id=m.count,.parent=3,.logical=i%31,.allocated=(i%7)*4096};built&=space_model_record(&m,&r,name);logical[i%80]+=r.logical;allocated[i%80]+=r.allocated;files[i%80]++;}CHECK("large mixed-case extension fixture admitted",built);
