 uint32_t n;sp_row *rows=space_model_rows(&m,3,1,0,0,L"moved",NULL,NULL,&n);CHECK("flat query includes lower-ID child moved into later folder",rows&&n==1&&rows[0].id==2);free(rows);
 rows=space_model_rows(&m,1,1,0,0,L"",NULL,NULL,&n);CHECK("old scope excludes moved child",rows&&n==0);free(rows);
 for(int metric=0;metric<2;metric++)for(int order=0;order<3;order++){rows=space_model_rows(&m,3,1,metric,order,L"item",NULL,NULL,&n);int okay=rows&&n==1200;for(uint32_t i=1;okay&&i<n;i++){sp_row *a=rows+i-1,*b=rows+i;int c=order==2?0:a->size>b->size?-1:a->size<b->size?1:0;if(order==1)c=-c;if(!c)c=_wcsicmp(m.nodes[a->id].name,m.nodes[b->id].name);if(!c)c=(a->id>b->id)-(a->id<b->id);okay=c<=0;}CHECK("all files and deterministic ordering retained for metric/sort",okay);free(rows);
  rows=space_model_rows(&m,3,2,metric,order,L"",NULL,NULL,&n);okay=rows&&n==83;uint64_t total=0,group_files=0;for(uint32_t i=0;okay&&i<n;i++){sp_row *a=rows+i;total+=a->logical;group_files+=a->files;if(a->type[0]==L'.'&&a->type[1]==L't'&&a->type[2]>=L'0'&&a->type[2]<=L'9'&&a->type[3]>=L'0'&&a->type[3]<=L'9'){unsigned k=(a->type[2]-L'0')*10+a->type[3]-L'0';okay=k<80&&a->logical==logical[k]&&a->allocated==allocated[k]&&a->files==files[k]&&a->size==(metric?allocated[k]:logical[k]);}}CHECK("hash groups retain exact counts and logical/allocated totals",okay&&total==m.nodes[3].sum.logical&&group_files==1205);free(rows);
 }
 rows=space_model_rows(&m,3,3,1,0,L"ITEM",L".t03",NULL,&n);CHECK("extension drilldown intersects case-insensitive filename filter",rows&&n==15);free(rows);rows=space_model_rows(&m,3,2,0,0,L"absent",NULL,NULL,&n);CHECK("empty type query is a valid empty result",rows&&n==0);free(rows);
