/* Observe real protocol output; no host clipboard/menu dispatch or physical input. */
typedef struct space_action_capture {HANDLE reader,writer,previous;} space_action_capture;
static int space_capture_begin(space_action_capture *c){memset(c,0,sizeof *c);if(!CreatePipe(&c->reader,&c->writer,NULL,65536))return 0;c->previous=A.out;A.out=c->writer;return 1;}
static void space_capture_end(space_action_capture *c){A.out=c->previous;CloseHandle(c->writer);CloseHandle(c->reader);}
static int space_capture_read(space_action_capture *c,space_action *action,wchar_t path[32768]){int count=0;DWORD have=0;while(PeekNamedPipe(c->reader,NULL,0,NULL,&have,NULL)&&have){panelp_head h;if(have<sizeof h||!io(c->reader,&h,sizeof h,0)||h.size>PANELP_MAX)return -1;uint8_t *data=malloc(h.size?h.size:1);if(!data)return -1;if(h.size&&!io(c->reader,data,h.size,0)){free(data);return -1;}if(h.type==PANELP_SPACE_ACTION){if(h.size<sizeof *action+2||(h.size-sizeof *action)%2){free(data);return -1;}uint32_t chars=(h.size-sizeof *action)/2;if(chars>32768){free(data);return -1;}memcpy(action,data,sizeof *action);memcpy(path,data+sizeof *action,chars*2);if(path[chars-1]||wcslen(path)!=chars-1){free(data);return -1;}count++;}free(data);}return count;}
static int space_capture_matches(space_action_capture *c,uint32_t kind,const wchar_t *path,uint32_t flags){space_action a={0};wchar_t actual[32768];return space_capture_read(c,&a,actual)==1&&a.session==A.request.session&&a.action==kind&&a.flags==flags&&!wcscmp(actual,path);}
static int space_capture_empty(space_action_capture *c){space_action a;wchar_t path[32768];return space_capture_read(c,&a,path)==0;}
static void space_key(UINT key,uint32_t mods){input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=key,.mods=mods});}
