/* Record actual DrawTextW input from the main browser, not only row metadata. */
static int metric_capture,rendered_metric,rendered_updating;
static struct {wchar_t name[48],value[96],percent[32];} metric_cells[2];
static void metric_observe(const wchar_t *value,const RECT *rect){
 if(!metric_capture||!value)return;if(!wcscmp(value,L"Logical"))rendered_metric=0;else if(!wcscmp(value,L"On disk"))rendered_metric=1;if(wcsstr(value,L"Previous order retained"))rendered_updating=1;
 int row=(rect->top-B.left.top)/S(34);if(rect->top<B.left.top||rect->top>=B.left.top+2*S(34)||row<0||row>1)return;
 if(!wcscmp(value,L".sparse")||!wcscmp(value,L".padded"))wcsncpy(metric_cells[row].name,value,47);
 else if(rect->right==B.left.right-S(57))wcsncpy(metric_cells[row].value,value,95);
 else if(rect->right==B.left.right-S(9))wcsncpy(metric_cells[row].percent,value,31);
}
static int metric_paint_matches(int allocated,int updating){
 memset(metric_cells,0,sizeof metric_cells);rendered_metric=-1;rendered_updating=0;metric_capture=1;paint(0);metric_capture=0;
 int seen=0,correct=rendered_metric==allocated&&rendered_updating==updating;
 for(int i=0;i<2;i++){if(!wcscmp(metric_cells[i].name,L".sparse")){seen|=1;correct&=!wcscmp(metric_cells[i].value,allocated?L"100 B":L"900 B")&&!wcscmp(metric_cells[i].percent,allocated?L"5.0%":L"90.0%");}else if(!wcscmp(metric_cells[i].name,L".padded")){seen|=2;correct&=!wcscmp(metric_cells[i].value,allocated?L"1.86 KiB":L"100 B")&&!wcscmp(metric_cells[i].percent,allocated?L"95.0%":L"10.0%");}}
 return correct&&seen==3;
}
