/* Only the owned UUID fixture's exact child can be chmod'd. A second restoration
 * guard lives in the PowerShell runner's finally block if this process fails. */
static int analysis_fixture_access(const wchar_t *root,int denied){
 wchar_t distro[128],path[32768],exe[MAX_PATH],cmd[36000];if(!term_wsl_split(root,distro,128,path,32768))return 0;
 for(const wchar_t *p=distro;*p;p++)if(!iswalnum(*p)&&*p!=L'-'&&*p!=L'_'&&*p!=L'.')return 0;
 UINT n=GetSystemDirectoryW(exe,MAX_PATH-10);if(!n||n>=MAX_PATH-10)return 0;wcscat(exe,L"\\wsl.exe");
 const wchar_t *script=L"import os,re,sys; p=sys.argv[1]; assert re.fullmatch('/tmp/openpilot-space-[0-9a-f]{32}/analysis',p); assert not os.path.islink(p); assert open(os.path.dirname(p)+'/.owner').read()=='openpilot-space/v1'; assert not os.path.islink(p+'/denied'); os.chmod(p+'/denied',0 if sys.argv[2]=='deny' else 448)";
 if(swprintf(cmd,36000,L"\"%ls\" --distribution %ls --exec python3 -c \"%ls\" \"%ls\" %ls",exe,distro,script,path,denied?L"deny":L"restore")<0)return 0;
 STARTUPINFOW si={sizeof si};PROCESS_INFORMATION pi={0};if(!CreateProcessW(exe,cmd,NULL,NULL,FALSE,CREATE_NO_WINDOW,NULL,NULL,&si,&pi))return 0;DWORD status=WaitForSingleObject(pi.hProcess,10000),code=1;if(status!=WAIT_OBJECT_0)TerminateProcess(pi.hProcess,1);else GetExitCodeProcess(pi.hProcess,&code);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);return status==WAIT_OBJECT_0&&!code;
}
